import sys
import threading


class Counter:
    def __init__(self):
        self.value = 0
        self._lock = threading.Lock()

    def increment(self):
        with self._lock:
            self.value += 1


def worker(counter: Counter, increments: int) -> None:
    for _ in range(increments):
        counter.increment()


def main() -> None:
    data = sys.stdin.read().split()
    if len(data) < 2:
        print("Final Counter: 0")
        return

    n = int(data[0])
    m = int(data[1])

    num_threads = n if n > 0 else 0
    increments_per_thread = m if m > 0 else 0

    counter = Counter()
    threads = []

    for _ in range(num_threads):
        t = threading.Thread(target=worker, args=(counter, increments_per_thread))
        threads.append(t)
        t.start()

    for t in threads:
        t.join()

    print(f"Final Counter: {counter.value}")


if __name__ == "__main__":
    main()
